        "status": "NOT_APPLICABLE_TO_THIS_QUESTION"
      },
      "source_support": {
        "evidence": [{"span_ids": ["s1"]}],
        "rationale": "Footnote 1 expressly gives public offering and ownership records as reasons for full responsibility despite outsourcing.",
