        "rationale": "This is the demonstration duty whose request condition the question tests.",
        "status": "RELEVANT"
      },
      "source_support": {
        "evidence": [{"span_ids": ["s3"]}, {"span_ids": ["s4"]}],
        "rationale": "Paragraph 14 expressly conditions demonstration on request and names all three subjects. Footnote 5 adds minimum substance; its independent effect remains interpretive.",
        "status": "SUPPORTED"
      }
    },
    {
      "authority": {
        "dependency_ids": [],
        "rationale": "The supplied register provision establishes this narrow claim.",
        "status": "NONE_DECLARED"
      },
      "executable_correspondence": {
        "rationale": "A request for register addresses is a separate request and duty.",
