        "rationale": "The quoted paragraph establishes the express trigger without additional external authority.",
        "status": "NONE_DECLARED"
      },
      "executable_correspondence": {
        "rationale": "An applicable paragraph 14 demonstration request is exactly the result fact, within provider scope. Satisfaction and substantive demonstration remain outside this trigger test.",
        "representation_quotes": ["e0", "e1"],
        "status": "PRESERVES"
      },
      "followup_questions": [],
      "pair": "p4",
