        "rationale": "Confirmation remains a separate duty; its performance does not determine whether demonstration was requested.",
        "status": "NOT_APPLICABLE_TO_THIS_QUESTION"
      },
      "source_support": {
        "evidence": [{"span_ids": ["s3"]}, {"span_ids": ["s4"]}],
        "rationale": "The placement of the request phrase most directly qualifies demonstration. Both passages retain confirmation; attachment of SFC satisfaction to confirmation is unresolved.",
        "status": "SUPPORTED"
      }
    },
    {
      "authority": {
        "dependency_ids": [],
