        "status": "NOT_APPLICABLE_TO_THIS_QUESTION"
      },
      "source_support": {
        "evidence": [{"span_ids": ["s13"]}],
        "rationale": "Paragraph 18 expressly states the controls, risks and timing in the claim.",
        "status": "SUPPORTED"
      }
    },
    {
      "authority": {
        "dependency_ids": [],
        "rationale": "The supplied wording supports identifying both readings. Which additional interpretive authority could conclusively resolve them is uncertain.",
        "status": "UNCERTAIN"
      },
      "executable_correspondence": {
        "rationale": "For this expressly harmonised trigger question, the request fact correctly yields no activation when false. This preserves the conditional reading, not a conclusion that the rival independent-duty reading is legally excluded.",
        "representation_quotes": ["e1"],
        "status": "PRESERVES"
      },
      "followup_questions": [
        "Is there authoritative SFC clarification of whether footnote 5 independently requires demonstration without a paragraph 14 request?"
      ],
      "pair": "p7",
      "question_relation": {
        "evidence": [{"span_ids": ["s3"]}, {"span_ids": ["s4"]}],
        "rationale": "The competing readings directly concern the significance of an absent request; the exact question selects the harmonised reading.",
        "status": "RELEVANT"
      },
      "source_support": {
        "evidence": [{"span_ids": ["s3"]}, {"span_ids": ["s4"]}],
        "rationale": "The body expressly qualifies demonstration by request, while the footnote repeats demonstration without that qualifier. Both readings are textually plausible, and neither absence of request nor the footnote establishes actual compliance.",
        "status": "SUPPORTED"
      }
    },
    {
      "authority": {
        "dependency_ids": [],
        "rationale": "The quoted valuation provision suffices for the conditional valuation duty.",
        "status": "NONE_DECLARED"
      },
      "executable_correspondence": {
