        "status": "NOT_APPLICABLE_TO_THIS_QUESTION"
      },
      "source_support": {
        "evidence": [{"span_ids": ["s9"]}],
        "rationale": "The second sentence expressly requires ongoing supervision and periodic review when a valuation third party is engaged.",
        "status": "SUPPORTED"
      }
    },
    {
      "authority": {
        "dependency_ids": [],
        "rationale": "The minimum-content reference is express. Missing portions of paragraphs 10–13 are source-completeness gaps, not identified additional external dependencies.",
        "status": "NONE_DECLARED"
      },
      "executable_correspondence": {
        "rationale": "The result fact refers specifically to paragraph 14 demonstration, whose minimum content the question supplies. Testing actual compliance with paragraphs 10–13 would improperly turn this activation test into a performance test.",
        "representation_quotes": ["e1"],
        "status": "PRESERVES"
      },
      "followup_questions": [
        "Can the complete paragraphs 10–13 be supplied before assessing the substance or adequacy of confirmation and demonstration?"
      ],
