      "question_relation": {
        "evidence": [{"span_ids": ["s4"]}, {"span_ids": ["s3"]}],
        "rationale": "Footnote 5 identifies the demonstration referenced by the exact question; its minimum content is not an additional activation prerequisite.",
        "status": "RELEVANT"
      },
      "source_support": {
        "evidence": [{"span_ids": ["s4"]}],
        "rationale": "Footnote 5 expressly includes compliance with paragraphs 10–13 as a minimum, alongside the smart-contract assurance proposition.",
        "status": "SUPPORTED"
      }
    },
    {
      "authority": {
        "dependency_ids": [],
        "rationale": "The separate legal-opinion request condition is supplied directly.",
