      "source_support": {
        "evidence": [{"span_ids": ["s6"]}, {"span_ids": ["s5"]}],
        "rationale": "The legal-opinion provision is expressly request-conditioned and does not enumerate the three subjects listed for audit or verification.",
        "status": "SUPPORTED"
      }
    },
    {
      "authority": {
